package com.primehr.rsp.evaluation.infrastructure;
import com.primehr.rsp.evaluation.domain.CommitteeMember; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*;
public interface CommitteeMemberRepository extends JpaRepository<CommitteeMember,String>{List<CommitteeMember> findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(String agency,String committee);void deleteByAgencyIdAndCommitteeId(String agency,String committee);boolean existsByAgencyIdAndCommitteeIdAndEmployeeNoIgnoreCase(String agency,String committee,String employee);@Query("select m from CommitteeMember m where m.agencyId=:agency and m.committeeId=:committee and upper(m.employeeNo)=upper(:employee) and m.effectiveFrom<=:date and (m.effectiveTo is null or m.effectiveTo>=:date)") Optional<CommitteeMember> findEffective(@Param("agency")String agency,@Param("committee")String committee,@Param("employee")String employee,@Param("date")LocalDate date);}
